// AddedEdges returns all edge names that were set/added in this mutation.
func (m *Mutation) AddedEdges() []string {
	edges := make([]string, 0, 4)
	if m.tenant != nil {
		edges = append(edges, EdgeTenant)
	}
	if m.inviter != nil {
		edges = append(edges, EdgeInviter)
	}
	if m.party != nil {
		edges = append(edges, EdgeParty)
	}
	if m.holder != nil {
		edges = append(edges, EdgeHolder)
	}
	return edges
}

// AddedIds returns all Ids (to other nodes) that were added for the given edge
// name in this mutation.
func (m *Mutation) AddedIds(name string) []ent.Value {
	switch name {
	case EdgeTenant:
		if id := m.tenant; id != nil {
			return []ent.Value{*id}
		}
	case EdgeInviter:
		if id := m.inviter; id != nil {
			return []ent.Value{*id}
		}
	case EdgeParty:
		if id := m.party; id != nil {
			return []ent.Value{*id}
		}
	case EdgeHolder:
		if id := m.holder; id != nil {
			return []ent.Value{*id}
		}
	}
	return nil
}

